import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  // root container
  const root = new ctx.THREE.Group();

  // create a simple plane geometry (default 1x1 units)
  const geometry = new ctx.THREE.PlaneGeometry(1, 1);

  // basic node material – will receive the texture later
  const material = new MeshBasicNodeMaterial({
    map: null,
    toneMapped: true,
    color: 0xffffff,
  });

  const mesh = new ctx.THREE.Mesh(geometry, material);
  root.add(mesh);

  // load texture asynchronously (function stays synchronous)
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // store any GSAP timelines for later cleanup (none used here)
  const timelines = [];

  // cleanup routine
  root.userData.cleanup = () => {
    timelines.forEach((t) => t.kill());
    material.dispose();
    geometry.dispose();
  };

  // placeholder for event handlers (none defined)
  root.userData.handlers = {};

  return root;
}
